// ==TEXTURAS-EMBEBIDAS== v1.0
// EL PROBLEMA (BUG-TEX1): un documento puede llevar dentro una copia de las texturas que usa
// (`doc.textures`), pensada para que el modelo se vea sin servidor. `ingestTextures` mete esa copia
// en `texDefs`/`roomDataCache` PISANDO al documento real, y el que la escribe (`embeddedTextures`)
// solo guarda `size` y `voxels`: se deja `caras`, `atravesable`, `aislante` e `inamovible`.
// Resultado: la flor embebida pierde su mascara de caras y en el Mundo sale con TODOS sus voxels
// (696 quads en vez de 300). Y como el editor guarda ese mismo recorte en localStorage
// ('voxelforge:current' <- localSnap()), el envenenamiento SOBREVIVE A RECARGAR: cada arranque
// llama a restore() -> ingestTextures() y vuelve a pisar la flor buena. Por eso en una ventana de
// incognito se ve bien y en la de siempre no.
//
// LA REGLA: la copia embebida es un RESPALDO, no la fuente. Si la clave tiene fuente propia en el
// servidor ('asset:...' o 'hab:...'), manda el fichero; la copia solo se usa si el fetch no trae nada.
// Para las claves sin fuente (dibujos sueltos, render offline) no cambia nada: la copia ES la fuente.
(function () {
  var VERSION = 'v1.4';
  var G = (typeof window !== 'undefined') ? window : globalThis;
  if (typeof ingestTextures !== 'function' || typeof roomDataCache === 'undefined') {
    console.warn('texturas-embebidas: no encuentro ingestTextures/roomDataCache; no se instala.');
    return;
  }
  G.game = G.game || {};

  function conFuente(k) { return /^(asset:|hab:)/.test(k); }
  function nCaras(d) { return (d && d.caras) ? Object.keys(d.caras).length : 0; }
  function nVox(d) { return (d && d.voxels) ? Object.keys(d.voxels).length : 0; }

  function respaldoDe(def) {
    return {
      size: (typeof texSize === 'function') ? texSize(def.size) : def.size,
      voxels: def.voxels || {},
      caras: def.caras || null,
      atravesable: !!def.atravesable, aislante: !!def.aislante, inamovible: !!def.inamovible
    };
  }

  // ---- LECTOR: el fichero gana a la copia embebida -------------------------------------------
  function ingestSano(doc) {
    if (!doc || !doc.textures) return;
    var sueltas = null;
    var pares = Object.entries(doc.textures);
    for (var i = 0; i < pares.length; i++) {
      var k = pares[i][0], def = pares[i][1];
      if (!conFuente(k)) { (sueltas = sueltas || {})[k] = def; continue; }
      // Ya hay algo cargado para esa clave: la copia embebida NUNCA lo pisa.
      if ((typeof texDefs !== 'undefined' && texDefs.has(k)) || roomDataCache.has(k)) continue;
      // getRoomData deja su propia promesa en la cache; la sustituimos por la nuestra, que se queda
      // con el respaldo solo si el servidor no devuelve nada (modo offline).
      let respaldo = respaldoDe(def);
      let p = getRoomData(k).then(
        function (real) { return (nVox(real) > 0) ? real : respaldo; },
        function () { return respaldo; }
      );
      roomDataCache.set(k, p);
    }
    if (sueltas) ingestSano._orig({ textures: sueltas });
  }

  // ---- ESCRITOR: que la copia embebida deje de nacer coja ------------------------------------
  function embSano() {
    var t = embSano._orig.apply(this, arguments);
    if (!t || typeof texDefs === 'undefined') return t;
    for (var k in t) {
      var d = texDefs.get(k);
      if (!d) continue;
      if (d.caras) t[k].caras = d.caras;
      if (d.atravesable) t[k].atravesable = true;
      if (d.aislante) t[k].aislante = true;
      if (d.inamovible) t[k].inamovible = true;
    }
    return t;
  }

  // ---- REPARAR lo que ya esta envenenado en ESTA pestaña -------------------------------------
  // El envenenamiento ocurre en restore(), al arrancar, antes de que exista este snippet: instalar
  // el lector evita el proximo, no deshace el de hace un segundo. Esto lo deshace.
  //
  // ⚠️ Las DOS carreras que hacian que al entrar se viera mal y solo se arreglara al romper un bloque:
  //   1) refrescar antes de que el Mundo exista no refresca nada (no hay chunks que re-mallar todavia)
  //      → `esperarMundo`.
  //   2) `mcTablaFina` no hornea: cuando falta la geometria fina llama a `mcCalientaFina`, que es
  //      ASINCRONA (mcFinoPend, app.js:7957). Mallar en ese instante pinta el material como cubo
  //      proyectado — con TODOS sus voxels, que es justo el sintoma → `esperarFinos`.
  // ⛔ Y NO se usa `mcRefreshSavedKey`: rehace la paleta entera y el atlas, y con el mundo recien
  //    cargado deja la pieza sin dibujar (probado: la flor desaparecia del todo).
  async function esperarMundo(tope) {
    var t0 = Date.now();
    while (Date.now() - t0 < (tope || 20000)) {
      if (typeof mc !== 'undefined' && mc.gl && mc.chunks && mc.chunks.size > 0) return true;
      await new Promise(function (r) { setTimeout(r, 120); });
    }
    return false;
  }
  async function esperarFinos(claves, tope) {
    var t0 = Date.now();
    while (Date.now() - t0 < (tope || 15000)) {
      var pend = (typeof mcFinoPend !== 'undefined' && mcFinoPend.size > 0);
      var faltan = claves.some(function (k) { return !mc.finoGeom[k]; });
      if (!pend && !faltan) return true;
      await new Promise(function (r) { setTimeout(r, 120); });
    }
    return false;
  }

  // ⛔ REQ-RED1 · QUIEN PUEDE ESTAR ENVENENADO SE SABE, NO SE ADIVINA.
  // El veneno lo mete `restore()` al arrancar y viene de un solo sitio: la copia embebida que el
  // editor guarda en localStorage. De esa copia solo hacen daño las COJAS —las que perdieron
  // `caras`— y de claves con fuente propia en el servidor, que es letra por letra lo que ya calcula
  // `limpiarLS()`. Esa lista, y ninguna otra, es la que hay que revisar.
  function sospechosas() {
    try {
      var d = JSON.parse(localStorage.getItem('voxelforge:current') || 'null');
      if (!d || !d.textures) return [];
      return Object.keys(d.textures).filter(function (k) {
        return conFuente(k) && !(d.textures[k] && d.textures[k].caras);
      });
    } catch (e) { return []; }
  }

  // `claves` = a quien revisar. Sin argumento se deduce de localStorage, para poder llamarlo a mano
  // con `game.texturasEmbebidas.revisar()`; `on()` la pasa ya hecha, porque para entonces
  // `limpiarLS()` ya ha borrado la prueba.
  async function reparar(claves) {
    if (typeof mc === 'undefined' || !mc.blockKey) return { revisadas: 0, arregladas: 0, claves: [] };
    // ANTES se barria `mc.blockKey` ENTERA y se invalidaba todo lo que no tuviera `caras`. Pero «sin
    // caras» es el estado NORMAL de cualquier textura 16³ maciza, o sea de casi toda la paleta: se
    // volvia a bajar el documento de cada material para descubrir dos lineas mas abajo que no habia
    // nada que cambiar. Medido en un mapa de 42 materiales: 24 documentos bajados DOS veces y 22
    // peticiones 404 repetidas, ~50 % del trafico de la carga, en cada entrada y en cada mapa.
    var lista = claves || sospechosas();
    var vistas = {}, arregladas = [];
    for (var i = 0; i < lista.length; i++) {
      var k = lista[i];
      if (!k || !conFuente(k)) continue;
      var base = (typeof mcClaveBase === 'function') ? mcClaveBase(k) : k;
      if (vistas[base]) continue;
      vistas[base] = 1;
      if (!roomDataCache.has(base)) continue;
      var cache = await roomDataCache.get(base);
      if (nCaras(cache) > 0) continue;               // tiene caras: no es la copia coja
      invalidateTex(base);                            // olvida def, repr, geometria y variantes giradas
      var real = await getRoomData(base);
      if (nVox(real) === 0) { roomDataCache.set(base, Promise.resolve(cache)); continue; }
      if (nCaras(real) === 0 && !!real.atravesable === !!cache.atravesable) continue;
      arregladas.push({ clave: base, de: nCaras(cache), a: nCaras(real) });
    }
    if (arregladas.length) {
      var claves = arregladas.map(function (a) { return a.clave; });
      await esperarMundo(20000);
      for (const kk of claves) if (typeof getTexDef === 'function') await getTexDef(kk);
      if (typeof mcTablaFina === 'function') mcTablaFina();   // encarga las geometrias que faltan
      await esperarFinos(claves, 15000);                       // …y espera a que lleguen
      if (typeof mcTablaFina === 'function') mcTablaFina();   // ahora si: la tabla con la geometria buena
      if (typeof mcMeshAll === 'function') await mcMeshAll();
      // Si alguna de las claves esta ESTAMPADA como estructura, su VBO horneo la version coja.
      try {
        if (mc.structures && mc.structures.some(function (s) { return claves.indexOf(s.key) >= 0; })
            && typeof mcRestampAll === 'function') await mcRestampAll();
      } catch (e) { console.warn('texturas-embebidas: re-estampado', e && e.message); }
    }
    return {
      revisadas: Object.keys(vistas).length, arregladas: arregladas.length,
      claves: arregladas.map(function (a) { return a.clave + ' (' + a.de + ' -> ' + a.a + ' caras)'; })
    };
  }

  // ---- SACAR EL VENENO DE DONDE VIVE: localStorage ------------------------------------------
  // Reparar la cache llega TARDE: `restore()` envenena al arrancar y el jugador ya ha visto el
  // primer fotograma con la pieza mal. La unica forma de que la proxima carga nazca limpia es
  // limpiar el recorte del editor. NO se borra el dibujo: solo se quitan de `textures` las copias
  // COJAS (sin `caras`) de claves que tienen fuente propia en el servidor — para esas, la copia no
  // aportaba nada, porque el fichero manda.
  function limpiarLS() {
    try {
      var raw = localStorage.getItem('voxelforge:current');
      if (!raw) return 0;
      var d = JSON.parse(raw);
      if (!d || !d.textures) return 0;
      var quitadas = [];
      for (var k in d.textures) {
        var def = d.textures[k];
        if (conFuente(k) && !(def && def.caras)) { delete d.textures[k]; quitadas.push(k); }
      }
      if (!quitadas.length) return 0;
      if (!Object.keys(d.textures).length) delete d.textures;
      localStorage.setItem('voxelforge:current', JSON.stringify(d));
      console.log('texturas-embebidas: limpiada la copia coja del editor (localStorage) → ' + quitadas.join(', ')
        + '. La proxima carga ya nace bien desde el primer fotograma.');
      return quitadas.length;
    } catch (e) { console.warn('texturas-embebidas: no se pudo limpiar localStorage:', e && e.message); return 0; }
  }

  function instalar() {
    if (!ingestTextures._sano) {
      ingestSano._orig = ingestTextures;
      ingestSano._sano = true;
      G.ingestTextures = ingestSano;
    }
    if (typeof embeddedTextures === 'function' && !embeddedTextures._sano) {
      embSano._orig = embeddedTextures;
      embSano._sano = true;
      G.embeddedTextures = embSano;
    }
  }
  function desinstalar() {
    if (ingestTextures._sano && ingestTextures._orig) G.ingestTextures = ingestTextures._orig;
    if (typeof embeddedTextures === 'function' && embeddedTextures._sano && embeddedTextures._orig)
      G.embeddedTextures = embeddedTextures._orig;
  }

  G.game.texturasEmbebidas = {
    on() {
      // Instalar es sincrono; la reparacion espera al Mundo y puede tardar segundos, asi que va en
      // segundo plano: el autoarranque no puede quedarse colgado esperandola. `listo` es su promesa.
      instalar();
      // ⚠️ ORDEN (REQ-RED1): se apunta a QUIEN reparar ANTES de limpiar, porque `limpiarLS()` borra
      // justo la prueba. Antes daba igual —se barria la paleta entera—; ahora que solo se mira a los
      // sospechosos, limpiar primero dejaria la lista vacia y no se repararia nada.
      var sosp = sospechosas();
      limpiarLS();          // lo primero: que la PROXIMA carga no tenga nada que reparar
      this.listo = reparar(sosp).then(function (r) {
        console.log('texturas-embebidas ' + VERSION + ': lector+escritor instalados · ' +
          r.arregladas + '/' + r.revisadas + ' textura(s) reparadas' +
          (r.claves.length ? ' → ' + r.claves.join(', ') : ''));
        return r;
      }, function (e) { console.warn('texturas-embebidas: reparación fallida:', e && e.message); });
      return this.listo;
    },
    off() { desinstalar(); console.log('texturas-embebidas: motor devuelto tal cual estaba.'); },
    revisar: reparar,
    limpiar: limpiarLS,
    estado() {
      return {
        version: VERSION,
        lector: !!(ingestTextures && ingestTextures._sano),
        escritor: !!(typeof embeddedTextures === 'function' && embeddedTextures._sano)
      };
    }
  };
})();

game.texturasEmbebidas.on();
